SELECT e.id, e.requester_branch_id, e.requester_staff_id, e.raw_request, e.medication_id, e.quantity, e.status, e.outcome, e.outcome_branch_id, e.handled_by, e.clarification_question, e.clarification_answer, e.wake_trigger, e.next_wake_at, e.created_at, e.updated_at, e.closed_at FROM enquiries e WHERE EXISTS (SELECT 1 FROM enquiry_targets t WHERE t.enquiry_id = e.id AND t.branch_id = $1 AND t.status NOT IN ('proposed','approved')) AND ($2::text = '' OR e.status = $2) ORDER BY e.created_at DESC, e.id LIMIT $3 OFFSET $4
